import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    def interpolate(value: str, section_name: str, sections: dict[str, dict[str, str]]) -> str:
        def replace(match):
            if ':' in match.group(1):
                sect, key = match.group(1).split(':', 1)
                if sect not in sections:
                    raise KeyError(f"Section '{sect}' not found")
                return sections[sect][key]
            else:
                key = match.group(1)
                if key in sections[section_name]:
                    return sections[section_name][key]
                elif 'DEFAULT' in sections and key in sections['DEFAULT']:
                    return sections['DEFAULT'][key]
                else:
                    raise KeyError(f"Key '{key}' not found in section '{section_name}'")

        while '${' in value:
            try:
                new_value = re.sub(r'\$\{([^}]+)\}', replace, value)
                if new_value == value:
                    raise ValueError("Interpolation cycle detected")
                value = new_value
            except KeyError as e:
                raise KeyError(str(e)) from None
        return value

    lines = text.splitlines()
    current_section = None
    sections = {}
    default_section = {}

    for line in lines:
        line = line.strip()

        if not line or line.startswith(';') or line.startswith('#'):
            continue

        if line.startswith('[') and line.endswith(']'):
            section_name = line[1:-1].strip()
            if not section_name:
                raise ValueError("Empty section name")
            current_section = section_name
            sections[current_section] = {}
            continue

        if '=' in line or ':' in line:
            if current_section is None:
                raise ValueError("Key outside of any section")

            delimiter = '=' if '=' in line else ':'
            key, value = line.split(delimiter, 1)
            key = key.strip().lower()
            value = value.strip()

            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]

            if ' ;' in value or ' #' in value:
                value = value[:value.find(' ;')].strip() if ' ;' in value else value[:value.find(' #')].strip()

            if line.startswith(' ') or line.startswith('\t'):
                if key not in sections[current_section]:
                    raise ValueError("Continuation line without preceding key")
                sections[current_section][key] += '\n' + value
            else:
                sections[current_section][key] = value

            if current_section != 'DEFAULT':
                if key in default_section:
                    sections[current_section][key] = default_section[key]
                sections[current_section][key] = interpolate(sections[current_section][key], current_section, sections)

        else:
            raise ValueError("Malformed line")

    if 'DEFAULT' in sections:
        default_section = sections.pop('DEFAULT')

    for section in sections.values():
        for key in list(section.keys()):
            if key in default_section and key not in section:
                section[key] = default_section[key]

    return sections
